from typing import Any


class ClassicalGnbPmcountersCollectorConfigurator:
    def add_pmcounters(self: Any, ne_log_name: str, ne_log_configuration: dict):
        """
        Add a new pmcounters collector configuration to the current list of collector configurations with
        all needed (sub-) collectors
        """
        webservice = self.tl_config_information_provider.get_web_service(self.ne_id)
        pmcounters_collector_configuration = {
            'name': f"{ne_log_name}",
            'type': "pmcounters",
            'webservice': webservice
        }

        for parameter_name, parameter_value in ne_log_configuration.items():
            if parameter_name in [
                'for_last',
                'intervals'
            ] and parameter_value is not None:
                pmcounters_collector_configuration[parameter_name] = parameter_value

        self._collector_configuration_data.append(pmcounters_collector_configuration)
        self._collector_configuration_data.add_mapping_entry(
            log_type='pmcounter',
            network_element=f'{self.ne_type}_{self.ne_id}',
            collector_configuration=pmcounters_collector_configuration)
